-- END MIGRATION: 20260718105030_operations_reporting_audit_barcode.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260719100000_reconcile_legacy_inventory_projections.sql
-- ============================================================================
begin;

do $$
begin
  if not exists (
    select 1
    from public.inventory_locations
    where code = 'MAIN_STORE'
      and active
  ) then
    raise exception 'INVENTORY_RUNTIME_UNAVAILABLE: active MAIN_STORE is required';
  end if;
end;
$$;

-- inventory_balances is authoritative. Older pre-release databases can have
-- correct balances while the compatibility fields on products still use the
-- legacy empty ONE SIZE representation. Bring those projections into the same
-- shape produced by the transactional product and inventory RPCs.
with expected_projection as (
  select
    p.id as product_id,
    coalesce((
      select pg_catalog.sum(b.quantity_on_hand)::integer
      from public.product_variants v
      join public.inventory_locations l
        on l.code = 'MAIN_STORE'
       and l.active
      join public.inventory_balances b
        on b.variant_id = v.id
       and b.location_id = l.id
      where v.product_id = p.id
        and v.active
    ), 0) as stock,
    coalesce((
      select pg_catalog.string_agg(
        pg_catalog.upper(pg_catalog.btrim(coalesce(v.size, 'ONE SIZE'))),
        ',' order by v.sort_order, v.id
      )
      from public.product_variants v
      where v.product_id = p.id
        and v.active
    ), '') as sizes,
    coalesce((
      select pg_catalog.jsonb_object_agg(
        x.size_label,
        x.quantity_on_hand
        order by x.sort_order, x.variant_id
      )
      from (
        select
          pg_catalog.upper(pg_catalog.btrim(coalesce(v.size, 'ONE SIZE'))) as size_label,
          b.quantity_on_hand,
          v.sort_order,
          v.id as variant_id
        from public.product_variants v
        join public.inventory_locations l
          on l.code = 'MAIN_STORE'
         and l.active
        join public.inventory_balances b
          on b.variant_id = v.id
         and b.location_id = l.id
        where v.product_id = p.id
          and v.active
      ) x
    ), '{}'::jsonb) as size_stock
  from public.products p
)
update public.products p
set
  stock = e.stock,
  sizes = e.sizes,
  size_stock = e.size_stock,
  updated_at = pg_catalog.now()
from expected_projection e
where e.product_id = p.id
  and (
    p.stock is distinct from e.stock
    or p.sizes is distinct from e.sizes
    or p.size_stock is distinct from e.size_stock
  );

commit;

-- END MIGRATION: 20260719100000_reconcile_legacy_inventory_projections.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260719110000_normalize_legacy_product_image_urls.sql
-- ============================================================================
begin;

-- Some pre-baseline customer databases created products.image_urls as text[].
-- The transactional product RPCs use the current jsonb array contract, so a
-- legacy text[] column makes every product create/update fail closed when the
-- expression is first planned. Normalize the column without changing any URL.
do $$
declare
  v_type text;
begin
  select pg_catalog.format_type(a.atttypid, a.atttypmod)
  into v_type
  from pg_catalog.pg_attribute a
  where a.attrelid = 'public.products'::pg_catalog.regclass
    and a.attname = 'image_urls'
    and not a.attisdropped;

  if v_type is null then
    raise exception 'products.image_urls is missing';
  elsif v_type = 'text[]' then
    alter table public.products alter column image_urls drop default;
    alter table public.products
      alter column image_urls type jsonb
      using pg_catalog.to_jsonb(coalesce(image_urls, array[]::text[]));
  elsif v_type <> 'jsonb' then
    raise exception 'Unsupported products.image_urls type: %', v_type;
  end if;

  if exists (
    select 1
    from public.products
    where image_urls is not null
      and pg_catalog.jsonb_typeof(image_urls) <> 'array'
  ) then
    raise exception 'products.image_urls contains a non-array JSON value';
  end if;

  update public.products
  set image_urls = '[]'::jsonb
  where image_urls is null;

  alter table public.products
    alter column image_urls set default '[]'::jsonb,
    alter column image_urls set not null;

  if not exists (
    select 1
    from pg_catalog.pg_constraint
    where conrelid = 'public.products'::pg_catalog.regclass
      and conname = 'products_image_urls_json_array_check'
  ) then
    alter table public.products
      add constraint products_image_urls_json_array_check
      check (pg_catalog.jsonb_typeof(image_urls) = 'array') not valid;
  end if;

  alter table public.products
    validate constraint products_image_urls_json_array_check;
end;
$$;

notify pgrst, 'reload schema';

commit;

-- END MIGRATION: 20260719110000_normalize_legacy_product_image_urls.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260719120000_transactional_bulk_barcode_generation.sql
-- ============================================================================
-- Generate only missing internal Variant barcodes in one payload-bound transaction.
-- Existing barcodes are always preserved. Barcode values remain derived from variant_sku.

create or replace function public.variant_barcodes_generate_missing_rpc(
  p_client_request_id text,
  p_variant_ids jsonb,
  p_actor text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_request_id text := pg_catalog.btrim(coalesce(p_client_request_id, ''));
  v_actor text := pg_catalog.btrim(coalesce(p_actor, ''));
  v_fingerprint text;
  v_existing public.barcode_operations%rowtype;
  v_variant_id uuid;
  v_variant record;
  v_barcode text;
  v_items jsonb := '[]'::jsonb;
  v_result jsonb;
  v_requested integer;
  v_generated integer := 0;
  v_skipped integer := 0;
  v_failed integer := 0;
begin
  if v_request_id = '' or pg_catalog.length(v_request_id) > 200 then
    raise exception using errcode = '22023', message = 'BARCODE_INVALID_REQUEST_ID';
  end if;
  if v_actor = '' or pg_catalog.length(v_actor) > 300 then
    raise exception using errcode = '22023', message = 'BARCODE_INVALID_ACTOR';
  end if;
  if p_variant_ids is null or pg_catalog.jsonb_typeof(p_variant_ids) <> 'array'
     or pg_catalog.jsonb_array_length(p_variant_ids) < 1
     or pg_catalog.jsonb_array_length(p_variant_ids) > 100 then
    raise exception using errcode = '22023', message = 'BARCODE_INVALID_VARIANT_IDS';
  end if;

  create temporary table if not exists pg_temp.barcode_variant_ids (
    variant_id uuid primary key
  ) on commit drop;
  truncate pg_temp.barcode_variant_ids;

  begin
    insert into pg_temp.barcode_variant_ids (variant_id)
    select distinct nullif(pg_catalog.btrim(value #>> '{}'), '')::uuid
    from pg_catalog.jsonb_array_elements(p_variant_ids);
  exception when others then
    raise exception using errcode = '22023', message = 'BARCODE_INVALID_VARIANT_IDS';
  end;

  select pg_catalog.count(*) into v_requested from pg_temp.barcode_variant_ids;
  if v_requested < 1 or v_requested > 100 then
    raise exception using errcode = '22023', message = 'BARCODE_INVALID_VARIANT_IDS';
  end if;

  select pg_catalog.encode(extensions.digest(
    pg_catalog.convert_to(
      'bulk-missing:' || coalesce(pg_catalog.jsonb_agg(variant_id order by variant_id)::text, '[]'),
      'UTF8'
    ),
    'sha256'::text
  ), 'hex')
  into v_fingerprint
  from pg_temp.barcode_variant_ids;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('barcode:' || v_request_id, 0));
  select * into v_existing
  from public.barcode_operations
  where client_request_id = v_request_id;
  if found then
    if v_existing.payload_fingerprint <> v_fingerprint
       or v_existing.actor <> v_actor
       or v_existing.mode <> 'variant_sku' then
      raise exception using errcode = '23505', message = 'BARCODE_OPERATION_CONFLICT';
    end if;
    return v_existing.result || pg_catalog.jsonb_build_object('already_processed', true);
  end if;

  for v_variant_id in
    select variant_id from pg_temp.barcode_variant_ids order by variant_id
  loop
    select id, variant_sku, barcode
    into v_variant
    from public.product_variants
    where id = v_variant_id
    for update;

    if not found then
      v_failed := v_failed + 1;
      v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'variantId', v_variant_id,
        'status', 'failed',
        'code', 'BARCODE_VARIANT_NOT_FOUND',
        'message', 'Variant does not exist.'
      ));
      continue;
    end if;

    if nullif(pg_catalog.btrim(coalesce(v_variant.barcode, '')), '') is not null then
      v_skipped := v_skipped + 1;
      v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'variantId', v_variant.id,
        'variantSku', v_variant.variant_sku,
        'barcode', v_variant.barcode,
        'status', 'skipped_existing'
      ));
      continue;
    end if;

    v_barcode := pg_catalog.btrim(coalesce(v_variant.variant_sku, ''));
    if v_barcode = '' or pg_catalog.length(v_barcode) > 200 then
      v_failed := v_failed + 1;
      v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'variantId', v_variant.id,
        'variantSku', v_variant.variant_sku,
        'status', 'failed',
        'code', 'BARCODE_INVALID_VARIANT_SKU',
        'message', 'Variant SKU cannot be used as an internal Barcode.'
      ));
      continue;
    end if;

    begin
      update public.product_variants
      set barcode = v_barcode,
          updated_at = pg_catalog.now()
      where id = v_variant.id
        and nullif(pg_catalog.btrim(coalesce(barcode, '')), '') is null;

      if found then
        v_generated := v_generated + 1;
        v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
          'variantId', v_variant.id,
          'variantSku', v_variant.variant_sku,
          'barcode', v_barcode,
          'status', 'generated'
        ));
      else
        select id, variant_sku, barcode
        into v_variant
        from public.product_variants
        where id = v_variant_id;
        v_skipped := v_skipped + 1;
        v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
          'variantId', v_variant.id,
          'variantSku', v_variant.variant_sku,
          'barcode', v_variant.barcode,
          'status', 'skipped_existing'
        ));
      end if;
    exception when unique_violation then
      v_failed := v_failed + 1;
      v_items := v_items || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
        'variantId', v_variant.id,
        'variantSku', v_variant.variant_sku,
        'status', 'failed',
        'code', 'BARCODE_ALREADY_IN_USE',
        'message', 'The generated internal Barcode is already assigned to another Variant.'
      ));
    end;
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'ok', v_failed = 0,
    'requested', v_requested,
    'generated', v_generated,
    'skipped_existing', v_skipped,
    'failed', v_failed,
    'items', v_items,
    'already_processed', false
  );

  insert into public.barcode_operations (client_request_id, payload_fingerprint, actor, mode, result)
  values (v_request_id, v_fingerprint, v_actor, 'variant_sku', v_result);

  insert into public.audit_logs (actor, action, entity, entity_id, metadata)
  values (
    v_actor,
    'variant_barcodes_generated_missing',
    'barcode_operation',
    v_request_id,
    pg_catalog.jsonb_build_object(
      'requested', v_requested,
      'generated', v_generated,
      'skippedExisting', v_skipped,
      'failed', v_failed
    )
  );

  return v_result;
end;
$$;

revoke all on function public.variant_barcodes_generate_missing_rpc(text, jsonb, text) from public, anon, authenticated;
grant execute on function public.variant_barcodes_generate_missing_rpc(text, jsonb, text) to service_role;

comment on function public.variant_barcodes_generate_missing_rpc(text, jsonb, text) is
  'Idempotently generates missing internal Variant Barcodes from immutable Variant SKUs; preserves existing Barcodes and reports per-item outcomes.';

-- END MIGRATION: 20260719120000_transactional_bulk_barcode_generation.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260801090000_multicolor_product_variants.sql
-- ============================================================================
begin;

-- A catalog Variant is a product + normalized size + normalized color. The
-- earlier pre-release RPC already persisted color, but rejected a second row
-- with the same size even when the color differed.
create unique index if not exists product_variants_product_size_color_ci_unique
on public.product_variants (
  product_id,
  pg_catalog.upper(pg_catalog.btrim(coalesce(size, 'ONE SIZE'))),
  pg_catalog.lower(pg_catalog.btrim(coalesce(color, '')))
);

create or replace function app_private.product_projection(p_product_id bigint)
returns table(stock integer, sizes text, size_stock jsonb)
language sql
stable
security definer
set search_path = ''
as $$
  with active_variants as (
    select
      pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(v.size, ''), 'ONE SIZE'))) as size_label,
      v.sort_order,
      v.id as variant_id,
      coalesce(b.quantity_on_hand, 0)::integer as quantity_on_hand
    from public.product_variants v
    join public.inventory_locations l
      on l.code = 'MAIN_STORE'
     and l.active
    left join public.inventory_balances b
      on b.variant_id = v.id
     and b.location_id = l.id
    where v.product_id = p_product_id
      and v.active
  ), size_totals as (
    select
      size_label,
      pg_catalog.min(sort_order) as sort_order,
      pg_catalog.sum(quantity_on_hand)::integer as quantity_on_hand
    from active_variants
    group by size_label
  )
  select
    coalesce(pg_catalog.sum(quantity_on_hand), 0)::integer as stock,
    coalesce(pg_catalog.string_agg(size_label, ',' order by sort_order, size_label), '') as sizes,
    coalesce(
      pg_catalog.jsonb_object_agg(size_label, quantity_on_hand order by sort_order, size_label),
      '{}'::jsonb
    ) as size_stock
  from size_totals;
$$;

revoke all on function app_private.product_projection(bigint)
from public, anon, authenticated, service_role;

create or replace function app_private.product_projection_before_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_projection record;
begin
  select * into v_projection
  from app_private.product_projection(new.id);

  new.stock := coalesce(v_projection.stock, 0);
  new.sizes := coalesce(v_projection.sizes, '');
  new.size_stock := coalesce(v_projection.size_stock, '{}'::jsonb);
  return new;
end;
$$;

revoke all on function app_private.product_projection_before_write()
from public, anon, authenticated, service_role;

drop trigger if exists products_authoritative_inventory_projection on public.products;
create trigger products_authoritative_inventory_projection
before update of stock, sizes, size_stock on public.products
for each row execute function app_private.product_projection_before_write();

-- Preserve the mature transaction functions and patch only their catalog-key
-- validation. Existing operation IDs, locks, stock movements, audit records,
-- and fail-closed behavior remain unchanged.
do $migration$
declare
  v_signature pg_catalog.regprocedure;
  v_definition text;
begin
  foreach v_signature in array array[
    'public.product_create_rpc(text,jsonb,jsonb,text,text)'::pg_catalog.regprocedure,
    'public.product_update_rpc(text,bigint,bigint,bigint,jsonb,jsonb,text,text)'::pg_catalog.regprocedure
  ]
  loop
    select pg_catalog.pg_get_functiondef(v_signature::oid) into v_definition;

    if pg_catalog.strpos(v_definition, 'v_seen_catalog_keys') = 0 then
      if pg_catalog.strpos(v_definition, 'v_seen_sizes') = 0 then
        raise exception 'MULTICOLOR_MIGRATION_PRECONDITION: expected product RPC catalog validation was not found';
      end if;
      v_definition := pg_catalog.replace(v_definition, 'v_seen_sizes', 'v_seen_catalog_keys');
      v_definition := pg_catalog.replace(
        v_definition,
        'v_size = any(v_seen_catalog_keys)',
        '(pg_catalog.lower(v_size) || pg_catalog.chr(31) || pg_catalog.lower(v_color)) = any(v_seen_catalog_keys)'
      );
      v_definition := pg_catalog.replace(
        v_definition,
        'pg_catalog.array_append(v_seen_catalog_keys, v_size)',
        'pg_catalog.array_append(v_seen_catalog_keys, pg_catalog.lower(v_size) || pg_catalog.chr(31) || pg_catalog.lower(v_color))'
      );
      v_definition := pg_catalog.replace(
        v_definition,
        'variant_sku and normalized size must be unique within a product catalog',
        'variant_sku and normalized size/color must be unique within a product catalog'
      );
      if pg_catalog.strpos(v_definition, 'v_seen_sizes') > 0
         or pg_catalog.strpos(v_definition, 'v_size = any(v_seen_catalog_keys)') > 0 then
        raise exception 'MULTICOLOR_MIGRATION_PRECONDITION: product RPC catalog validation patch was incomplete';
      end if;
      execute v_definition;
    end if;
  end loop;
end;
$migration$;

-- The compatibility projection is intentionally size-only for legacy readers.
-- Multiple colors of L therefore produce one L key whose value is the sum of
-- all L Variants. Keep the mature reconciliation checks and replace only its
-- projection result through a private legacy implementation plus safe wrapper.
alter function public.product_reconciliation_rpc() set schema app_private;
alter function app_private.product_reconciliation_rpc() rename to product_reconciliation_legacy_rpc;
revoke all on function app_private.product_reconciliation_legacy_rpc()
from public, anon, authenticated, service_role;

create or replace function public.product_reconciliation_rpc()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_legacy jsonb;
  v_projection_mismatches jsonb;
  v_healthy boolean;
begin
  v_legacy := app_private.product_reconciliation_legacy_rpc();

  with mismatches as (
    select
      p.id as product_id,
      p.sku,
      p.stock as actual_stock,
      projection.stock as expected_stock,
      p.sizes as actual_sizes,
      projection.sizes as expected_sizes,
      p.size_stock as actual_size_stock,
      projection.size_stock as expected_size_stock
    from public.products p
    cross join lateral app_private.product_projection(p.id) projection
    where p.stock is distinct from projection.stock
       or p.sizes is distinct from projection.sizes
       or p.size_stock is distinct from projection.size_stock
  )
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'product_id', product_id,
        'sku', sku,
        'actual_stock', actual_stock,
        'expected_stock', expected_stock,
        'actual_sizes', actual_sizes,
        'expected_sizes', expected_sizes,
        'actual_size_stock', actual_size_stock,
        'expected_size_stock', expected_size_stock
      ) order by product_id
    ),
    '[]'::jsonb
  ) into v_projection_mismatches
  from mismatches;

  v_healthy := pg_catalog.jsonb_array_length(v_projection_mismatches) = 0
    and pg_catalog.jsonb_array_length(coalesce(v_legacy -> 'productsMissingVariants', '[]'::jsonb)) = 0
    and pg_catalog.jsonb_array_length(coalesce(v_legacy -> 'variantsMissingMainStoreBalances', '[]'::jsonb)) = 0
    and pg_catalog.jsonb_array_length(coalesce(v_legacy -> 'inactiveVariantsWithReserved', '[]'::jsonb)) = 0
    and pg_catalog.jsonb_array_length(coalesce(v_legacy -> 'hardenedProductsMissingCreateOperation', '[]'::jsonb)) = 0
    and pg_catalog.jsonb_array_length(coalesce(v_legacy -> 'initialMovementMismatches', '[]'::jsonb)) = 0;

  return v_legacy || pg_catalog.jsonb_build_object(
    'healthy', v_healthy,
    'projectionMismatches', v_projection_mismatches,
    'checked_at', pg_catalog.now()
  );
end;
$$;

revoke execute on function public.product_reconciliation_rpc()
from public, anon, authenticated;
grant execute on function public.product_reconciliation_rpc()
to service_role;

create or replace function public.product_public_variants_rpc(p_product_sku text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sku text := pg_catalog.btrim(coalesce(p_product_sku, ''));
  v_result jsonb;
begin
  if v_sku = '' or pg_catalog.length(v_sku) > 200 then
    return '[]'::jsonb;
  end if;

  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'size', pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(v.size, ''), 'ONE SIZE'))),
        'color', pg_catalog.btrim(coalesce(v.color, '')),
        'quantity_available', greatest(coalesce(b.quantity_on_hand, 0) - coalesce(b.quantity_reserved, 0), 0)
      )
      order by v.sort_order, v.id
    ),
    '[]'::jsonb
  ) into v_result
  from public.products p
  join public.product_variants v
    on v.product_id = p.id
   and v.active
  join public.inventory_locations l
    on l.code = 'MAIN_STORE'
   and l.active
  left join public.inventory_balances b
    on b.variant_id = v.id
   and b.location_id = l.id
  where pg_catalog.lower(pg_catalog.btrim(p.sku)) = pg_catalog.lower(v_sku)
    and p.is_active is distinct from false;

  return coalesce(v_result, '[]'::jsonb);
end;
$$;

revoke all on function public.product_public_variants_rpc(text) from public;
grant execute on function public.product_public_variants_rpc(text) to anon, authenticated, service_role;

create or replace function public.product_public_variants_batch_rpc(p_product_skus text[])
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with requested as (
    select distinct pg_catalog.btrim(value) as sku
    from pg_catalog.unnest(coalesce(p_product_skus, '{}'::text[])) as input(value)
    where pg_catalog.btrim(value) <> ''
      and pg_catalog.length(pg_catalog.btrim(value)) <= 200
    limit 20
  ), variant_rows as (
    select
      p.sku,
      v.sort_order,
      v.id,
      pg_catalog.jsonb_build_object(
        'size', pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(v.size, ''), 'ONE SIZE'))),
        'color', pg_catalog.btrim(coalesce(v.color, '')),
        'quantity_available', greatest(coalesce(b.quantity_on_hand, 0) - coalesce(b.quantity_reserved, 0), 0)
      ) as item
    from requested r
    join public.products p
      on pg_catalog.lower(pg_catalog.btrim(p.sku)) = pg_catalog.lower(r.sku)
     and p.is_active is distinct from false
    join public.product_variants v
      on v.product_id = p.id
     and v.active
    join public.inventory_locations l
      on l.code = 'MAIN_STORE'
     and l.active
    left join public.inventory_balances b
      on b.variant_id = v.id
     and b.location_id = l.id
  ), grouped as (
    select sku, pg_catalog.jsonb_agg(item order by sort_order, id) as variants
    from variant_rows
    group by sku
  )
  select coalesce(pg_catalog.jsonb_object_agg(sku, variants), '{}'::jsonb)
  from grouped;
$$;

revoke all on function public.product_public_variants_batch_rpc(text[]) from public;
grant execute on function public.product_public_variants_batch_rpc(text[]) to anon, authenticated, service_role;

-- Repair compatibility projections for pre-existing products without changing
-- any authoritative Variant balance.
update public.products
set stock = stock,
    sizes = sizes,
    size_stock = size_stock;

commit;

-- END MIGRATION: 20260801090000_multicolor_product_variants.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260801191232_transactional_category_catalog.sql
-- ============================================================================
begin;

create or replace function public.category_catalog_apply_rpc(
  p_categories jsonb,
  p_subcategories jsonb,
  p_deleted_category_ids uuid[] default '{}'::uuid[],
  p_deleted_subcategory_ids uuid[] default '{}'::uuid[]
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_category_slug text;
  v_subcategory_slug text;
  v_saved_categories integer := 0;
  v_saved_subcategories integer := 0;
  v_deleted_categories integer := 0;
  v_deleted_subcategories integer := 0;
begin
  if jsonb_typeof(p_categories) <> 'array' or jsonb_typeof(p_subcategories) <> 'array' then
    raise exception 'CATEGORY_CATALOG_INVALID_PAYLOAD' using errcode = '22023';
  end if;

  if jsonb_array_length(p_categories) > 100 or jsonb_array_length(p_subcategories) > 1000 then
    raise exception 'CATEGORY_CATALOG_LIMIT_EXCEEDED' using errcode = '22023';
  end if;

  if exists (
    select 1
    from public.product_categories existing
    join jsonb_to_recordset(p_categories) as incoming(id uuid, slug text)
      on incoming.id = existing.id
    where incoming.slug is distinct from existing.slug
  ) then
    raise exception 'CATEGORY_SLUG_IMMUTABLE' using errcode = 'P0001';
  end if;

  if exists (
    select 1
    from public.product_subcategories existing
    join jsonb_to_recordset(p_subcategories) as incoming(id uuid, category_id uuid, slug text)
      on incoming.id = existing.id
    where incoming.slug is distinct from existing.slug
       or incoming.category_id is distinct from existing.category_id
  ) then
    raise exception 'SUBCATEGORY_IDENTITY_IMMUTABLE' using errcode = 'P0001';
  end if;

  select category.slug
  into v_category_slug
  from public.product_categories category
  where category.id = any(coalesce(p_deleted_category_ids, '{}'::uuid[]))
    and exists (
      select 1
      from public.products product
      where product.category = category.slug
    )
  order by category.slug
  limit 1;

  if v_category_slug is not null then
    raise exception 'CATEGORY_IN_USE:%', v_category_slug using errcode = 'P0001';
  end if;

  select category.slug, subcategory.slug
  into v_category_slug, v_subcategory_slug
  from public.product_subcategories subcategory
  join public.product_categories category on category.id = subcategory.category_id
  where subcategory.id = any(coalesce(p_deleted_subcategory_ids, '{}'::uuid[]))
    and exists (
      select 1
      from public.products product
      where product.category = category.slug
        and product.subcategory = subcategory.slug
    )
  order by category.slug, subcategory.slug
  limit 1;

  if v_subcategory_slug is not null then
    raise exception 'SUBCATEGORY_IN_USE:%/%', v_category_slug, v_subcategory_slug using errcode = 'P0001';
  end if;

  insert into public.product_categories (
    id,
    slug,
    name_cn,
    name_en,
    name_gr,
    image_url,
    sort_order,
    is_active
  )
  select
    incoming.id,
    incoming.slug,
    incoming.name_cn,
    incoming.name_en,
    incoming.name_gr,
    incoming.image_url,
    incoming.sort_order,
    incoming.is_active
  from jsonb_to_recordset(p_categories) as incoming(
    id uuid,
    slug text,
    name_cn text,
    name_en text,
    name_gr text,
    image_url text,
    sort_order integer,
    is_active boolean
  )
  on conflict (id) do update set
    name_cn = excluded.name_cn,
    name_en = excluded.name_en,
    name_gr = excluded.name_gr,
    image_url = excluded.image_url,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active;
  get diagnostics v_saved_categories = row_count;

  insert into public.product_subcategories (
    id,
    category_id,
    slug,
    name_cn,
    name_en,
    name_gr,
    sort_order,
    is_active
  )
  select
    incoming.id,
    incoming.category_id,
    incoming.slug,
    incoming.name_cn,
    incoming.name_en,
    incoming.name_gr,
    incoming.sort_order,
    incoming.is_active
  from jsonb_to_recordset(p_subcategories) as incoming(
    id uuid,
    category_id uuid,
    slug text,
    name_cn text,
    name_en text,
    name_gr text,
    sort_order integer,
    is_active boolean
  )
  on conflict (id) do update set
    name_cn = excluded.name_cn,
    name_en = excluded.name_en,
    name_gr = excluded.name_gr,
    sort_order = excluded.sort_order,
    is_active = excluded.is_active;
  get diagnostics v_saved_subcategories = row_count;

  delete from public.product_subcategories
  where id = any(coalesce(p_deleted_subcategory_ids, '{}'::uuid[]));
  get diagnostics v_deleted_subcategories = row_count;

  delete from public.product_categories
  where id = any(coalesce(p_deleted_category_ids, '{}'::uuid[]));
  get diagnostics v_deleted_categories = row_count;

  if not exists (select 1 from public.product_categories where is_active = true) then
    raise exception 'ACTIVE_CATEGORY_REQUIRED' using errcode = 'P0001';
  end if;

  return jsonb_build_object(
    'ok', true,
    'savedCategories', v_saved_categories,
    'savedSubcategories', v_saved_subcategories,
    'deletedCategories', v_deleted_categories,
    'deletedSubcategories', v_deleted_subcategories
  );
end;
$$;

revoke all on function public.category_catalog_apply_rpc(jsonb, jsonb, uuid[], uuid[]) from public, anon, authenticated;
grant execute on function public.category_catalog_apply_rpc(jsonb, jsonb, uuid[], uuid[]) to service_role;

commit;

-- END MIGRATION: 20260801191232_transactional_category_catalog.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260802103000_repair_legacy_category_timestamps.sql
-- ============================================================================
begin;

-- Some existing customer databases created the category tables before the
-- baseline schema added updated_at. Keep this forward upgrade self-contained:
-- the trigger helper may also be absent on those databases.
create or replace function public.set_updated_at()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  new.updated_at = pg_catalog.now();
  return new;
end;
$$;

alter table public.product_categories
  add column if not exists updated_at timestamptz;

update public.product_categories
set updated_at = coalesce(created_at, pg_catalog.now())
where updated_at is null;

alter table public.product_categories
  alter column updated_at set default pg_catalog.now(),
  alter column updated_at set not null;

drop trigger if exists categories_updated_at on public.product_categories;
create trigger categories_updated_at
before update on public.product_categories
for each row execute function public.set_updated_at();

alter table public.product_subcategories
  add column if not exists updated_at timestamptz;

update public.product_subcategories
set updated_at = coalesce(created_at, pg_catalog.now())
where updated_at is null;

alter table public.product_subcategories
  alter column updated_at set default pg_catalog.now(),
  alter column updated_at set not null;

drop trigger if exists subcategories_updated_at on public.product_subcategories;
create trigger subcategories_updated_at
before update on public.product_subcategories
for each row execute function public.set_updated_at();

commit;

-- END MIGRATION: 20260802103000_repair_legacy_category_timestamps.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260802120000_online_store_orders.sql
-- ============================================================================
begin;

create extension if not exists pgcrypto;

alter table public.business_settings
  add column if not exists online_store_enabled boolean not null default false,
  add column if not exists delivery_enabled boolean not null default true,
  add column if not exists pickup_enabled boolean not null default true,
  add column if not exists shipping_fee numeric(10,2) not null default 0,
  add column if not exists free_shipping_threshold numeric(10,2),
  add column if not exists pickup_instructions_en text,
  add column if not exists pickup_instructions_gr text,
  add column if not exists delivery_instructions_en text,
  add column if not exists delivery_instructions_gr text,
  add column if not exists order_notification_email text;

alter table public.business_settings
  drop constraint if exists business_settings_shipping_fee_check,
  add constraint business_settings_shipping_fee_check check (shipping_fee >= 0),
  drop constraint if exists business_settings_free_shipping_threshold_check,
  add constraint business_settings_free_shipping_threshold_check
    check (free_shipping_threshold is null or free_shipping_threshold >= 0);

create table if not exists public.online_orders (
  id uuid primary key default gen_random_uuid(),
  order_number text not null unique,
  status text not null default 'pending',
  fulfillment_method text not null,
  payment_method text not null,
  payment_status text not null default 'pending',
  subtotal numeric(10,2) not null,
  shipping_total numeric(10,2) not null default 0,
  total numeric(10,2) not null,
  currency text not null default 'EUR',
  customer_name text not null,
  customer_email text not null,
  customer_phone text not null,
  address_line1 text,
  city text,
  postal_code text,
  country text not null default 'GR',
  customer_notes text,
  locale text not null default 'el',
  idempotency_key text not null unique,
  request_fingerprint text not null,
  access_token_hash text not null,
  legal_terms_version text,
  privacy_policy_version text,
  legal_accepted_at timestamptz not null,
  confirmed_at timestamptz,
  ready_at timestamptz,
  shipped_at timestamptz,
  completed_at timestamptz,
  cancelled_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint online_orders_status_check check (
    status in ('pending', 'confirmed', 'ready_for_pickup', 'shipped', 'completed', 'cancelled')
  ),
  constraint online_orders_fulfillment_check check (fulfillment_method in ('delivery', 'pickup')),
  constraint online_orders_payment_method_check check (payment_method in ('cash_on_delivery', 'pay_at_pickup')),
  constraint online_orders_payment_status_check check (payment_status in ('pending', 'paid', 'cancelled')),
  constraint online_orders_amount_check check (subtotal >= 0 and shipping_total >= 0 and total >= 0),
  constraint online_orders_delivery_address_check check (
    fulfillment_method <> 'delivery'
    or (
      nullif(btrim(coalesce(address_line1, '')), '') is not null
      and nullif(btrim(coalesce(city, '')), '') is not null
      and nullif(btrim(coalesce(postal_code, '')), '') is not null
    )
  )
);

create table if not exists public.online_order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.online_orders(id) on delete restrict,
  product_id bigint not null references public.products(id) on delete restrict,
  variant_id uuid not null references public.product_variants(id) on delete restrict,
  product_sku text not null,
  variant_sku text not null,
  name_en text not null,
  name_gr text not null,
  size text not null,
  color text not null default '',
  quantity integer not null,
  unit_price numeric(10,2) not null,
  line_total numeric(10,2) not null,
  image_url text,
  created_at timestamptz not null default now(),
  constraint online_order_items_quantity_check check (quantity > 0),
  constraint online_order_items_amount_check check (unit_price >= 0 and line_total >= 0),
  unique (order_id, variant_id)
);

create table if not exists public.online_order_operations (
  operation_id text primary key,
  order_id uuid not null references public.online_orders(id) on delete restrict,
  action text not null,
  request_fingerprint text not null,
  result jsonb not null,
  actor text not null,
  created_at timestamptz not null default now()
);

create table if not exists public.online_order_rate_limits (
  subject_hash text primary key,
  window_started_at timestamptz not null default now(),
  attempts integer not null default 0,
  updated_at timestamptz not null default now(),
  constraint online_order_rate_limits_attempts_check check (attempts >= 0)
);

create index if not exists online_orders_created_at_idx on public.online_orders(created_at desc);
create index if not exists online_orders_status_idx on public.online_orders(status, created_at desc);
create index if not exists online_orders_customer_email_idx on public.online_orders(lower(customer_email));
create index if not exists online_order_items_order_id_idx on public.online_order_items(order_id);
create index if not exists online_order_items_variant_id_idx on public.online_order_items(variant_id);
create index if not exists online_order_operations_order_id_idx on public.online_order_operations(order_id, created_at desc);

alter table public.online_orders enable row level security;
alter table public.online_order_items enable row level security;
alter table public.online_order_operations enable row level security;
alter table public.online_order_rate_limits enable row level security;

revoke all on table public.online_orders from anon, authenticated;
revoke all on table public.online_order_items from anon, authenticated;
revoke all on table public.online_order_operations from anon, authenticated;
revoke all on table public.online_order_rate_limits from anon, authenticated;
grant select, insert, update, delete on table public.online_orders to service_role;
grant select, insert, update, delete on table public.online_order_items to service_role;
grant select, insert, update, delete on table public.online_order_operations to service_role;
grant select, insert, update, delete on table public.online_order_rate_limits to service_role;

create or replace function app_private.online_order_payload(p_order_id uuid, p_replayed boolean default false)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select pg_catalog.jsonb_build_object(
    'id', o.id,
    'orderNumber', o.order_number,
    'status', o.status,
    'fulfillmentMethod', o.fulfillment_method,
    'paymentMethod', o.payment_method,
    'paymentStatus', o.payment_status,
    'subtotal', o.subtotal,
    'shippingTotal', o.shipping_total,
    'total', o.total,
    'currency', o.currency,
    'createdAt', o.created_at,
    'replayed', p_replayed,
    'items', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'productSku', i.product_sku,
        'variantSku', i.variant_sku,
        'nameEn', i.name_en,
        'nameGr', i.name_gr,
        'size', i.size,
        'color', i.color,
        'quantity', i.quantity,
        'unitPrice', i.unit_price,
        'lineTotal', i.line_total,
        'imageUrl', i.image_url
      ) order by i.created_at, i.id)
      from public.online_order_items i where i.order_id = o.id
    ), '[]'::jsonb)
  )
  from public.online_orders o
  where o.id = p_order_id;
$$;

revoke all on function app_private.online_order_payload(uuid, boolean)
from public, anon, authenticated, service_role;

create or replace function public.online_order_rate_limit_rpc(
  p_subject_hash text,
  p_limit integer default 10,
  p_window_seconds integer default 900
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_now timestamptz := pg_catalog.now();
  v_row public.online_order_rate_limits%rowtype;
begin
  if nullif(pg_catalog.btrim(coalesce(p_subject_hash, '')), '') is null
     or p_limit < 1 or p_limit > 100
     or p_window_seconds < 60 or p_window_seconds > 86400 then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_RATE_LIMIT_INVALID';
  end if;

  insert into public.online_order_rate_limits(subject_hash, attempts)
  values (p_subject_hash, 0)
  on conflict (subject_hash) do nothing;

  select * into v_row
  from public.online_order_rate_limits
  where subject_hash = p_subject_hash
  for update;

  if v_row.window_started_at <= v_now - pg_catalog.make_interval(secs => p_window_seconds) then
    update public.online_order_rate_limits
    set window_started_at = v_now, attempts = 1, updated_at = v_now
    where subject_hash = p_subject_hash;
    return pg_catalog.jsonb_build_object('allowed', true, 'remaining', p_limit - 1, 'retryAfter', 0);
  end if;

  update public.online_order_rate_limits
  set attempts = attempts + 1, updated_at = v_now
  where subject_hash = p_subject_hash
  returning * into v_row;

  return pg_catalog.jsonb_build_object(
    'allowed', v_row.attempts <= p_limit,
    'remaining', greatest(p_limit - v_row.attempts, 0),
    'retryAfter', case
      when v_row.attempts <= p_limit then 0
      else greatest(
        1,
        pg_catalog.ceil(extract(epoch from (v_row.window_started_at + pg_catalog.make_interval(secs => p_window_seconds) - v_now)))::integer
      )
    end
  );
end;
$$;

revoke all on function public.online_order_rate_limit_rpc(text, integer, integer) from public, anon, authenticated;
grant execute on function public.online_order_rate_limit_rpc(text, integer, integer) to service_role;

create or replace function public.online_order_create_rpc(
  p_operation_id text,
  p_request_fingerprint text,
  p_access_token_hash text,
  p_customer jsonb,
  p_items jsonb,
  p_fulfillment_method text,
  p_payment_method text,
  p_shipping_fee numeric,
  p_free_shipping_threshold numeric,
  p_locale text,
  p_legal_terms_version text,
  p_privacy_policy_version text,
  p_legal_accepted_at timestamptz
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_existing public.online_orders%rowtype;
  v_order_id uuid;
  v_order_number text;
  v_subtotal numeric(10,2) := 0;
  v_shipping numeric(10,2) := pg_catalog.round(greatest(coalesce(p_shipping_fee, 0), 0), 2);
  v_requested_count integer;
  v_resolved_count integer;
  v_row record;
  v_attempt integer;
  v_customer_name text := pg_catalog.btrim(coalesce(p_customer ->> 'name', ''));
  v_customer_email text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_customer ->> 'email', '')));
  v_customer_phone text := pg_catalog.btrim(coalesce(p_customer ->> 'phone', ''));
  v_address text := nullif(pg_catalog.btrim(coalesce(p_customer ->> 'addressLine1', '')), '');
  v_city text := nullif(pg_catalog.btrim(coalesce(p_customer ->> 'city', '')), '');
  v_postal_code text := nullif(pg_catalog.btrim(coalesce(p_customer ->> 'postalCode', '')), '');
begin
  if nullif(pg_catalog.btrim(coalesce(p_operation_id, '')), '') is null
     or nullif(pg_catalog.btrim(coalesce(p_request_fingerprint, '')), '') is null
     or nullif(pg_catalog.btrim(coalesce(p_access_token_hash, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_IDENTITY';
  end if;

  select * into v_existing from public.online_orders where idempotency_key = p_operation_id;
  if found then
    if v_existing.request_fingerprint <> p_request_fingerprint
       or v_existing.access_token_hash <> p_access_token_hash then
      raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_IDEMPOTENCY_CONFLICT';
    end if;
    return app_private.online_order_payload(v_existing.id, true);
  end if;

  if p_fulfillment_method not in ('delivery', 'pickup')
     or p_payment_method not in ('cash_on_delivery', 'pay_at_pickup')
     or (p_fulfillment_method = 'delivery' and p_payment_method <> 'cash_on_delivery')
     or (p_fulfillment_method = 'pickup' and p_payment_method <> 'pay_at_pickup') then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_FULFILLMENT';
  end if;

  if pg_catalog.length(v_customer_name) < 2 or pg_catalog.length(v_customer_name) > 120
     or pg_catalog.length(v_customer_email) < 5 or pg_catalog.length(v_customer_email) > 200
     or pg_catalog.length(v_customer_phone) < 6 or pg_catalog.length(v_customer_phone) > 40 then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_CUSTOMER';
  end if;
  if p_fulfillment_method = 'delivery' and (v_address is null or v_city is null or v_postal_code is null) then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_DELIVERY_ADDRESS_REQUIRED';
  end if;
  if p_legal_accepted_at is null
     or nullif(pg_catalog.btrim(coalesce(p_legal_terms_version, '')), '') is null
     or nullif(pg_catalog.btrim(coalesce(p_privacy_policy_version, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_LEGAL_ACCEPTANCE_REQUIRED';
  end if;
  if pg_catalog.jsonb_typeof(p_items) <> 'array' or pg_catalog.jsonb_array_length(p_items) < 1 or pg_catalog.jsonb_array_length(p_items) > 25 then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_ITEMS';
  end if;

  create temporary table if not exists online_order_resolved_items (
    product_id bigint not null,
    variant_id uuid not null,
    product_sku text not null,
    variant_sku text not null,
    name_en text not null,
    name_gr text not null,
    size text not null,
    color text not null,
    image_url text,
    quantity integer not null,
    unit_price numeric(10,2) not null,
    line_total numeric(10,2) not null,
    balance_id uuid not null,
    quantity_on_hand integer not null,
    quantity_reserved integer not null,
    primary key (variant_id)
  ) on commit drop;
  truncate table online_order_resolved_items;

  create temporary table if not exists online_order_requested_items (
    product_sku_key text not null,
    size_key text not null,
    color_key text not null,
    quantity integer not null,
    primary key (product_sku_key, size_key, color_key)
  ) on commit drop;
  truncate table online_order_requested_items;

  if exists (
    select 1
    from pg_catalog.jsonb_array_elements(p_items) item(value)
    where pg_catalog.jsonb_typeof(value) <> 'object'
       or nullif(pg_catalog.btrim(coalesce(value ->> 'productSku', '')), '') is null
       or coalesce(value ->> 'quantity', '') !~ '^[1-9][0-9]*$'
       or (value ->> 'quantity')::integer > 20
       or pg_catalog.length(pg_catalog.btrim(coalesce(value ->> 'size', ''))) > 60
       or pg_catalog.length(pg_catalog.btrim(coalesce(value ->> 'color', ''))) > 100
  ) then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_ITEMS';
  end if;

  insert into online_order_requested_items(product_sku_key, size_key, color_key, quantity)
  select
    pg_catalog.lower(pg_catalog.btrim(value ->> 'productSku')),
    pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(value ->> 'size', ''), 'ONE SIZE'))),
    pg_catalog.lower(pg_catalog.btrim(coalesce(value ->> 'color', ''))),
    pg_catalog.sum((value ->> 'quantity')::integer)::integer
  from pg_catalog.jsonb_array_elements(p_items) item(value)
  group by 1,2,3;

  if exists (select 1 from online_order_requested_items where quantity > 20) then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_ITEMS';
  end if;

  select count(*) into v_requested_count from online_order_requested_items;

  if v_requested_count < 1 or v_requested_count > 25 then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_ITEMS';
  end if;

  insert into online_order_resolved_items
  select
    p.id,
    v.id,
    p.sku,
    v.variant_sku,
    coalesce(nullif(p.name_en, ''), nullif(p.name_gr, ''), p.sku),
    coalesce(nullif(p.name_gr, ''), nullif(p.name_en, ''), p.sku),
    pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(v.size, ''), 'ONE SIZE'))),
    pg_catalog.btrim(coalesce(v.color, '')),
    nullif(p.image_url, ''),
    r.quantity,
    pg_catalog.round(coalesce(v.price, p.price, 0)::numeric, 2),
    pg_catalog.round(coalesce(v.price, p.price, 0)::numeric * r.quantity, 2),
    b.id,
    b.quantity_on_hand,
    b.quantity_reserved
  from online_order_requested_items r
  join public.products p on pg_catalog.lower(pg_catalog.btrim(p.sku)) = r.product_sku_key and p.is_active is distinct from false
  join public.product_variants v on v.product_id = p.id and v.active
    and pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(v.size, ''), 'ONE SIZE'))) = r.size_key
    and pg_catalog.lower(pg_catalog.btrim(coalesce(v.color, ''))) = r.color_key
  join public.inventory_locations l on l.code = 'MAIN_STORE' and l.active
  join public.inventory_balances b on b.variant_id = v.id and b.location_id = l.id
  where r.quantity between 1 and 20
  order by v.id
  for update of b;

  select count(*) into v_resolved_count from online_order_resolved_items;
  if v_resolved_count <> v_requested_count then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_ITEM_UNAVAILABLE';
  end if;

  for v_row in select * from online_order_resolved_items order by variant_id loop
    if v_row.quantity_on_hand - v_row.quantity_reserved < v_row.quantity then
      raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INSUFFICIENT_STOCK';
    end if;
  end loop;

  select coalesce(pg_catalog.sum(line_total), 0)::numeric(10,2) into v_subtotal from online_order_resolved_items;
  if p_fulfillment_method = 'pickup'
     or (p_free_shipping_threshold is not null and v_subtotal >= greatest(p_free_shipping_threshold, 0)) then
    v_shipping := 0;
  end if;

  for v_attempt in 1..5 loop
    begin
      v_order_number := 'WEB-' || pg_catalog.to_char(pg_catalog.now(), 'YYYYMMDD-HH24MISS') || '-' || pg_catalog.upper(pg_catalog.substr(pg_catalog.replace(pg_catalog.gen_random_uuid()::text, '-', ''), 1, 6));
      insert into public.online_orders(
        order_number, fulfillment_method, payment_method, subtotal, shipping_total, total,
        customer_name, customer_email, customer_phone, address_line1, city, postal_code,
        customer_notes, locale, idempotency_key, request_fingerprint, access_token_hash,
        legal_terms_version, privacy_policy_version, legal_accepted_at
      ) values (
        v_order_number, p_fulfillment_method, p_payment_method, v_subtotal, v_shipping, v_subtotal + v_shipping,
        v_customer_name, v_customer_email, v_customer_phone, v_address, v_city, v_postal_code,
        nullif(pg_catalog.btrim(coalesce(p_customer ->> 'notes', '')), ''),
        case when p_locale = 'en' then 'en' else 'el' end,
        p_operation_id, p_request_fingerprint, p_access_token_hash,
        p_legal_terms_version, p_privacy_policy_version, p_legal_accepted_at
      ) returning id into v_order_id;
      exit;
    exception when unique_violation then
      select * into v_existing from public.online_orders where idempotency_key = p_operation_id;
      if found then
        if v_existing.request_fingerprint <> p_request_fingerprint or v_existing.access_token_hash <> p_access_token_hash then
          raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_IDEMPOTENCY_CONFLICT';
        end if;
        return app_private.online_order_payload(v_existing.id, true);
      end if;
      if v_attempt = 5 then raise; end if;
    end;
  end loop;

  insert into public.online_order_items(
    order_id, product_id, variant_id, product_sku, variant_sku, name_en, name_gr,
    size, color, quantity, unit_price, line_total, image_url
  )
  select v_order_id, product_id, variant_id, product_sku, variant_sku, name_en, name_gr,
    size, color, quantity, unit_price, line_total, image_url
  from online_order_resolved_items;

  for v_row in select * from online_order_resolved_items order by variant_id loop
    update public.inventory_balances
    set quantity_reserved = quantity_reserved + v_row.quantity, updated_at = pg_catalog.now()
    where id = v_row.balance_id;

    insert into public.stock_movements(
      variant_id, location_id, movement_type, quantity_delta, quantity_before, quantity_after,
      reason, source_type, source_id, idempotency_key, created_by
    ) select
      v_row.variant_id, l.id, 'reservation', 0, v_row.quantity_on_hand, v_row.quantity_on_hand,
      'Online order inventory reservation', 'online_order', v_order_id::text,
      p_operation_id || ':' || v_row.variant_id::text || ':reserve', 'storefront'
    from public.inventory_locations l where l.code = 'MAIN_STORE' and l.active;
  end loop;

  return app_private.online_order_payload(v_order_id, false);
end;
$$;

revoke all on function public.online_order_create_rpc(text,text,text,jsonb,jsonb,text,text,numeric,numeric,text,text,text,timestamptz)
from public, anon, authenticated;
grant execute on function public.online_order_create_rpc(text,text,text,jsonb,jsonb,text,text,numeric,numeric,text,text,text,timestamptz)
to service_role;

create or replace function public.online_order_transition_rpc(
  p_order_id uuid,
  p_target_status text,
  p_operation_id text,
  p_actor text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_order public.online_orders%rowtype;
  v_existing public.online_order_operations%rowtype;
  v_row record;
  v_result jsonb;
begin
  if nullif(pg_catalog.btrim(coalesce(p_operation_id, '')), '') is null
     or nullif(pg_catalog.btrim(coalesce(p_actor, '')), '') is null then
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_OPERATION';
  end if;
  select * into v_existing from public.online_order_operations where operation_id = p_operation_id;
  if found then
    if v_existing.order_id <> p_order_id or v_existing.action <> p_target_status then
      raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_OPERATION_CONFLICT';
    end if;
    return v_existing.result || pg_catalog.jsonb_build_object('replayed', true);
  end if;

  select * into v_order from public.online_orders where id = p_order_id for update;
  if not found then raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_NOT_FOUND'; end if;
  if v_order.status = p_target_status then return app_private.online_order_payload(v_order.id, true); end if;

  if p_target_status = 'confirmed' and v_order.status = 'pending' then
    update public.online_orders set status='confirmed', confirmed_at=pg_catalog.now(), updated_at=pg_catalog.now() where id=v_order.id;
  elsif p_target_status = 'ready_for_pickup' and v_order.status = 'confirmed' and v_order.fulfillment_method = 'pickup' then
    update public.online_orders set status='ready_for_pickup', ready_at=pg_catalog.now(), updated_at=pg_catalog.now() where id=v_order.id;
  elsif p_target_status = 'shipped' and v_order.status = 'confirmed' and v_order.fulfillment_method = 'delivery' then
    update public.online_orders set status='shipped', shipped_at=pg_catalog.now(), updated_at=pg_catalog.now() where id=v_order.id;
  elsif p_target_status = 'cancelled' and v_order.status in ('pending','confirmed','ready_for_pickup') then
    for v_row in
      select i.variant_id, i.quantity, b.id as balance_id, b.quantity_on_hand, b.quantity_reserved, l.id as location_id
      from public.online_order_items i
      join public.inventory_locations l on l.code='MAIN_STORE' and l.active
      join public.inventory_balances b on b.variant_id=i.variant_id and b.location_id=l.id
      where i.order_id=v_order.id order by i.variant_id for update of b
    loop
      if v_row.quantity_reserved < v_row.quantity then
        raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_RECONCILIATION_REQUIRED';
      end if;
      update public.inventory_balances set quantity_reserved=quantity_reserved-v_row.quantity, updated_at=pg_catalog.now() where id=v_row.balance_id;
      insert into public.stock_movements(variant_id,location_id,movement_type,quantity_delta,quantity_before,quantity_after,reason,source_type,source_id,idempotency_key,created_by)
      values(v_row.variant_id,v_row.location_id,'release_reservation',0,v_row.quantity_on_hand,v_row.quantity_on_hand,'Online order cancelled','online_order',v_order.id::text,p_operation_id||':'||v_row.variant_id::text||':release',p_actor);
    end loop;
    update public.online_orders set status='cancelled',payment_status='cancelled',cancelled_at=pg_catalog.now(),updated_at=pg_catalog.now() where id=v_order.id;
  elsif p_target_status = 'completed' and ((v_order.status='ready_for_pickup' and v_order.fulfillment_method='pickup') or (v_order.status='shipped' and v_order.fulfillment_method='delivery')) then
    for v_row in
      select i.product_id,i.variant_id,i.quantity,b.id as balance_id,b.quantity_on_hand,b.quantity_reserved,l.id as location_id
      from public.online_order_items i
      join public.inventory_locations l on l.code='MAIN_STORE' and l.active
      join public.inventory_balances b on b.variant_id=i.variant_id and b.location_id=l.id
      where i.order_id=v_order.id order by i.variant_id for update of b
    loop
      if v_row.quantity_reserved < v_row.quantity or v_row.quantity_on_hand < v_row.quantity then
        raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_RECONCILIATION_REQUIRED';
      end if;
      update public.inventory_balances
      set quantity_on_hand=quantity_on_hand-v_row.quantity,quantity_reserved=quantity_reserved-v_row.quantity,updated_at=pg_catalog.now()
      where id=v_row.balance_id;
      insert into public.stock_movements(variant_id,location_id,movement_type,quantity_delta,quantity_before,quantity_after,reason,source_type,source_id,idempotency_key,created_by)
      values(v_row.variant_id,v_row.location_id,'sale',0-v_row.quantity,v_row.quantity_on_hand,v_row.quantity_on_hand-v_row.quantity,'Online order completed','online_order',v_order.id::text,p_operation_id||':'||v_row.variant_id::text||':sale',p_actor);
      update public.products set stock=stock,sizes=sizes,size_stock=size_stock where id=v_row.product_id;
    end loop;
    update public.online_orders set status='completed',payment_status='paid',completed_at=pg_catalog.now(),updated_at=pg_catalog.now() where id=v_order.id;
  else
    raise exception using errcode = 'P0001', message = 'ONLINE_ORDER_INVALID_TRANSITION';
  end if;

  v_result := app_private.online_order_payload(v_order.id, false);
  insert into public.online_order_operations(operation_id,order_id,action,request_fingerprint,result,actor)
  values(p_operation_id,v_order.id,p_target_status,p_target_status,v_result,p_actor);
  return v_result;
end;
$$;

revoke all on function public.online_order_transition_rpc(uuid,text,text,text) from public, anon, authenticated;
grant execute on function public.online_order_transition_rpc(uuid,text,text,text) to service_role;

-- The storefront needs the same server-authoritative Variant price used by the
-- checkout transaction so the cart never displays a stale product base price.
create or replace function public.product_public_variants_rpc(p_product_sku text)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_sku text := pg_catalog.btrim(coalesce(p_product_sku, ''));
  v_result jsonb;
begin
  if v_sku = '' or pg_catalog.length(v_sku) > 200 then return '[]'::jsonb; end if;
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'size', pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(v.size, ''), 'ONE SIZE'))),
    'color', pg_catalog.btrim(coalesce(v.color, '')),
    'price', pg_catalog.round(coalesce(v.price, p.price, 0)::numeric, 2),
    'quantity_available', greatest(coalesce(b.quantity_on_hand, 0) - coalesce(b.quantity_reserved, 0), 0)
  ) order by v.sort_order, v.id), '[]'::jsonb) into v_result
  from public.products p
  join public.product_variants v on v.product_id=p.id and v.active
  join public.inventory_locations l on l.code='MAIN_STORE' and l.active
  left join public.inventory_balances b on b.variant_id=v.id and b.location_id=l.id
  where pg_catalog.lower(pg_catalog.btrim(p.sku))=pg_catalog.lower(v_sku)
    and p.is_active is distinct from false;
  return coalesce(v_result, '[]'::jsonb);
end;
$$;

revoke all on function public.product_public_variants_rpc(text) from public;
grant execute on function public.product_public_variants_rpc(text) to anon, authenticated, service_role;

create or replace function public.product_public_variants_batch_rpc(p_product_skus text[])
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with requested as (
    select distinct pg_catalog.btrim(value) as sku
    from pg_catalog.unnest(coalesce(p_product_skus, '{}'::text[])) as input(value)
    where pg_catalog.btrim(value) <> '' and pg_catalog.length(pg_catalog.btrim(value)) <= 200
    limit 20
  ), variant_rows as (
    select p.sku, v.sort_order, v.id, pg_catalog.jsonb_build_object(
      'size', pg_catalog.upper(pg_catalog.btrim(coalesce(nullif(v.size, ''), 'ONE SIZE'))),
      'color', pg_catalog.btrim(coalesce(v.color, '')),
      'price', pg_catalog.round(coalesce(v.price, p.price, 0)::numeric, 2),
      'quantity_available', greatest(coalesce(b.quantity_on_hand, 0) - coalesce(b.quantity_reserved, 0), 0)
    ) as item
    from requested r
    join public.products p on pg_catalog.lower(pg_catalog.btrim(p.sku))=pg_catalog.lower(r.sku) and p.is_active is distinct from false
    join public.product_variants v on v.product_id=p.id and v.active
    join public.inventory_locations l on l.code='MAIN_STORE' and l.active
    left join public.inventory_balances b on b.variant_id=v.id and b.location_id=l.id
  ), grouped as (
    select sku, pg_catalog.jsonb_agg(item order by sort_order,id) as variants from variant_rows group by sku
  )
  select coalesce(pg_catalog.jsonb_object_agg(sku,variants), '{}'::jsonb) from grouped;
$$;

revoke all on function public.product_public_variants_batch_rpc(text[]) from public;
grant execute on function public.product_public_variants_batch_rpc(text[]) to anon, authenticated, service_role;

commit;

-- END MIGRATION: 20260802120000_online_store_orders.sql

-- ============================================================================
-- BEGIN MIGRATION: 20260904184454_transactional_inventory_receipts.sql
-- ============================================================================
begin;

create table public.inventory_receipts (
  id uuid primary key default gen_random_uuid(),
  receipt_number text not null unique,
  client_request_id text not null unique,
  payload_fingerprint text not null,
  supplier_id uuid references public.suppliers(id) on delete restrict,
  supplier_reference text,
  status text not null default 'completed',
  received_at timestamptz not null default now(),
  notes text,
  total_units integer not null,
  created_by text not null,
  result jsonb not null,
  created_at timestamptz not null default now(),
  completed_at timestamptz not null default now(),
  constraint inventory_receipts_status_check check (status in ('completed', 'cancelled')),
  constraint inventory_receipts_total_units_check check (total_units > 0),
  constraint inventory_receipts_request_not_blank check (btrim(client_request_id) <> ''),
  constraint inventory_receipts_actor_not_blank check (btrim(created_by) <> '')
);

create table public.inventory_receipt_items (
  id uuid primary key default gen_random_uuid(),
  receipt_id uuid not null references public.inventory_receipts(id) on delete restrict,
  variant_id uuid not null references public.product_variants(id) on delete restrict,
  quantity_received integer not null,
  unit_cost numeric(12,2),
  product_name_snapshot text not null,
  product_sku_snapshot text not null,
  variant_sku_snapshot text not null,
  barcode_snapshot text not null,
  price_snapshot numeric(12,2) not null,
  size_snapshot text,
  color_snapshot text,
  quantity_before integer not null,
  quantity_after integer not null,
  movement_id uuid not null references public.stock_movements(id) on delete restrict,
  created_at timestamptz not null default now(),
  unique (receipt_id, variant_id),
  constraint inventory_receipt_items_quantity_check check (
    quantity_received > 0
    and quantity_before >= 0
    and quantity_after = quantity_before + quantity_received
  ),
  constraint inventory_receipt_items_cost_check check (unit_cost is null or unit_cost >= 0),
  constraint inventory_receipt_items_sku_not_blank check (btrim(variant_sku_snapshot) <> ''),
  constraint inventory_receipt_items_barcode_not_blank check (btrim(barcode_snapshot) <> '')
);

create index inventory_receipts_received_idx on public.inventory_receipts (received_at desc);
create index inventory_receipts_supplier_idx on public.inventory_receipts (supplier_id, received_at desc);
create index inventory_receipt_items_variant_idx on public.inventory_receipt_items (variant_id, created_at desc);

alter table public.inventory_receipts enable row level security;
alter table public.inventory_receipt_items enable row level security;
revoke all on table public.inventory_receipts, public.inventory_receipt_items from public, anon, authenticated;
grant select, insert, update, delete on table public.inventory_receipts, public.inventory_receipt_items to service_role;

create or replace function public.inventory_receipt_complete_rpc(
  p_client_request_id text,
  p_supplier_id uuid,
  p_supplier_reference text,
  p_notes text,
  p_items jsonb,
  p_created_by text
)
returns jsonb
language plpgsql
security definer
set search_path = ''
set statement_timeout = '15s'
as $$
declare
  v_request_id text := pg_catalog.btrim(coalesce(p_client_request_id, ''));
  v_supplier_reference text := nullif(pg_catalog.btrim(coalesce(p_supplier_reference, '')), '');
  v_notes text := nullif(pg_catalog.btrim(coalesce(p_notes, '')), '');
  v_actor text := pg_catalog.btrim(coalesce(p_created_by, ''));
  v_fingerprint text;
  v_existing public.inventory_receipts%rowtype;
  v_receipt_id uuid := extensions.gen_random_uuid();
  v_receipt_number text;
  v_location_id uuid;
  v_item record;
  v_variant record;
  v_balance record;
  v_before integer;
  v_after integer;
  v_movement_id uuid;
  v_total_units integer;
  v_count integer;
  v_stock integer;
  v_size_stock jsonb;
  v_sizes text;
  v_items_result jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if v_request_id = '' or pg_catalog.length(v_request_id) > 128 then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: invalid clientRequestId';
  end if;
  if v_actor = '' or pg_catalog.length(v_actor) > 200 then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: invalid actor';
  end if;
  if v_supplier_reference is not null and pg_catalog.length(v_supplier_reference) > 160 then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: supplier reference is too long';
  end if;
  if v_notes is not null and pg_catalog.length(v_notes) > 500 then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: notes are too long';
  end if;
  if p_items is null or pg_catalog.jsonb_typeof(p_items) <> 'array'
     or pg_catalog.jsonb_array_length(p_items) < 1
     or pg_catalog.jsonb_array_length(p_items) > 100 then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: items must contain 1 to 100 rows';
  end if;

  create temporary table if not exists pg_temp.receipt_items_input (
    variant_id uuid primary key,
    quantity integer not null,
    unit_cost numeric(12,2)
  ) on commit drop;
  truncate pg_temp.receipt_items_input;

  begin
    insert into pg_temp.receipt_items_input (variant_id, quantity, unit_cost)
    select
      (row.item->>'variantId')::uuid,
      (row.item->>'quantity')::integer,
      case when nullif(row.item->>'unitCost', '') is null then null else (row.item->>'unitCost')::numeric end
    from pg_catalog.jsonb_array_elements(p_items) as row(item);
  exception when unique_violation then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: duplicate Variant';
  when others then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: malformed item';
  end;

  if exists (
    select 1 from pg_temp.receipt_items_input
    where quantity <= 0 or quantity > 1000000 or unit_cost < 0 or unit_cost > 10000000
  ) then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: invalid quantity or unit cost';
  end if;
  select pg_catalog.count(*), pg_catalog.sum(quantity)::integer
  into v_count, v_total_units from pg_temp.receipt_items_input;
  if v_count < 1 or v_count > 100 or v_total_units > 1000000 then
    raise exception using errcode = '22023', message = 'INVENTORY_RECEIPT_INVALID_ARGUMENT: receipt is too large';
  end if;

  select pg_catalog.encode(extensions.digest(pg_catalog.convert_to(
    coalesce(p_supplier_id::text, '') || '|' || coalesce(v_supplier_reference, '') || '|' || coalesce(v_notes, '') || '|' ||
    coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'variantId', variant_id, 'quantity', quantity, 'unitCost', unit_cost
    ) order by variant_id)::text, '[]'), 'UTF8'), 'sha256'::text), 'hex')
  into v_fingerprint from pg_temp.receipt_items_input;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('inventory-receipt:' || v_request_id, 0));
  select * into v_existing from public.inventory_receipts where client_request_id = v_request_id for update;
  if found then
    if v_existing.payload_fingerprint <> v_fingerprint or v_existing.created_by <> v_actor then
      raise exception using errcode = '23505', message = 'INVENTORY_RECEIPT_CONFLICT';
    end if;
    return pg_catalog.jsonb_set(v_existing.result, '{alreadyProcessed}', 'true'::jsonb, true);
  end if;

  if p_supplier_id is not null and not exists (
    select 1 from public.suppliers where id = p_supplier_id and active is distinct from false
  ) then
    raise exception using errcode = '23503', message = 'INVENTORY_RECEIPT_SUPPLIER_NOT_FOUND';
  end if;

  select id into v_location_id from public.inventory_locations
  where code = 'MAIN_STORE' and active is distinct from false limit 1;
  if v_location_id is null then
    raise exception using errcode = '23503', message = 'INVENTORY_RECEIPT_RUNTIME_UNAVAILABLE: MAIN_STORE is missing';
  end if;

  if (select count(*) from public.product_variants v join pg_temp.receipt_items_input i on i.variant_id = v.id) <> v_count then
    raise exception using errcode = '23503', message = 'INVENTORY_RECEIPT_VARIANT_NOT_FOUND';
  end if;
  if exists (
    select 1 from public.product_variants v join pg_temp.receipt_items_input i on i.variant_id = v.id
    join public.products p on p.id = v.product_id
    where v.active is false or p.is_active is false or nullif(pg_catalog.btrim(v.variant_sku), '') is null
  ) then
    raise exception using errcode = '23514', message = 'INVENTORY_RECEIPT_VARIANT_INACTIVE';
  end if;

  -- Lock in stable order so concurrent receipts cannot deadlock or lose increments.
  perform v.id from public.product_variants v join pg_temp.receipt_items_input i on i.variant_id = v.id order by v.id for update of v;
  perform p.id from public.products p where p.id in (
    select v.product_id from public.product_variants v join pg_temp.receipt_items_input i on i.variant_id = v.id
  ) order by p.id for update of p;

  -- Missing internal barcodes use the established immutable Variant SKU rule.
  update public.product_variants v set barcode = pg_catalog.btrim(v.variant_sku), updated_at = pg_catalog.now()
  from pg_temp.receipt_items_input i
  where v.id = i.variant_id and nullif(pg_catalog.btrim(coalesce(v.barcode, '')), '') is null;

  v_receipt_number := 'RCV-' || pg_catalog.to_char(pg_catalog.clock_timestamp(), 'YYYYMMDD') || '-' || pg_catalog.upper(pg_catalog.substr(pg_catalog.replace(v_receipt_id::text, '-', ''), 1, 12));
  insert into public.inventory_receipts (
    id, receipt_number, client_request_id, payload_fingerprint, supplier_id,
    supplier_reference, status, notes, total_units, created_by, result
  ) values (
    v_receipt_id, v_receipt_number, v_request_id, v_fingerprint, p_supplier_id,
    v_supplier_reference, 'completed', v_notes, v_total_units, v_actor, '{}'::jsonb
  );

  for v_item in select * from pg_temp.receipt_items_input order by variant_id loop
    select v.id, v.product_id, v.variant_sku, v.barcode, v.size, v.color,
           coalesce(v.price, p.price, 0) as price,
           p.sku as product_sku,
           coalesce(nullif(p.name_en, ''), nullif(p.name_gr, ''), nullif(p.name_cn, ''), p.sku) as product_name
    into v_variant from public.product_variants v join public.products p on p.id = v.product_id
    where v.id = v_item.variant_id;

    insert into public.inventory_balances (variant_id, location_id, quantity_on_hand, quantity_reserved, updated_at)
    values (v_item.variant_id, v_location_id, 0, 0, pg_catalog.now())
    on conflict (variant_id, location_id) do nothing;
    select id, quantity_on_hand, quantity_reserved into v_balance
    from public.inventory_balances where variant_id = v_item.variant_id and location_id = v_location_id for update;
    if not found then raise exception 'INVENTORY_RECEIPT_INVARIANT: balance unavailable'; end if;

    v_before := v_balance.quantity_on_hand;
    v_after := v_before + v_item.quantity;
    update public.inventory_balances set quantity_on_hand = v_after, updated_at = pg_catalog.now() where id = v_balance.id;
    if v_item.unit_cost is not null then
      update public.product_variants set cost_price = v_item.unit_cost, updated_at = pg_catalog.now() where id = v_item.variant_id;
    end if;

    insert into public.stock_movements (
      variant_id, location_id, movement_type, quantity_delta, quantity_before, quantity_after,
      reason, source_type, source_id, idempotency_key, created_by
    ) values (
      v_item.variant_id, v_location_id, 'transfer_in', v_item.quantity, v_before, v_after,
      coalesce('Receipt ' || v_supplier_reference, 'Inventory receipt'), 'inventory_receipt', v_receipt_id::text,
      'inventory-receipt:' || v_request_id || ':' || v_item.variant_id::text, v_actor
    ) returning id into v_movement_id;

    insert into public.inventory_receipt_items (
      receipt_id, variant_id, quantity_received, unit_cost, product_name_snapshot, product_sku_snapshot,
      variant_sku_snapshot, barcode_snapshot, price_snapshot, size_snapshot, color_snapshot,
      quantity_before, quantity_after, movement_id
    ) values (
      v_receipt_id, v_item.variant_id, v_item.quantity, v_item.unit_cost, v_variant.product_name,
      v_variant.product_sku, v_variant.variant_sku, v_variant.barcode, v_variant.price,
      v_variant.size, v_variant.color, v_before, v_after, v_movement_id
    );
    v_items_result := v_items_result || pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object(
      'variantId', v_item.variant_id, 'productId', v_variant.product_id, 'variantSku', v_variant.variant_sku,
      'barcode', v_variant.barcode, 'size', v_variant.size, 'color', v_variant.color,
      'quantityReceived', v_item.quantity, 'quantityBefore', v_before, 'quantityAfter', v_after,
      'movementId', v_movement_id
    ));
  end loop;

  for v_item in select distinct v.product_id from public.product_variants v join pg_temp.receipt_items_input i on i.variant_id = v.id loop
    with active_variants as (
      select coalesce(nullif(pg_catalog.btrim(v.size), ''), 'ONE SIZE') as size, v.sort_order,
             coalesce(b.quantity_on_hand, 0)::integer as quantity_on_hand
      from public.product_variants v left join public.inventory_balances b
        on b.variant_id = v.id and b.location_id = v_location_id
      where v.product_id = v_item.product_id and v.active is distinct from false
    ), size_totals as (
      select size, pg_catalog.min(sort_order) as sort_order, pg_catalog.sum(quantity_on_hand)::integer quantity_on_hand
      from active_variants group by size
    )
    select coalesce(pg_catalog.sum(quantity_on_hand), 0)::integer,
           coalesce(pg_catalog.jsonb_object_agg(size, quantity_on_hand order by sort_order, size), '{"ONE SIZE":0}'::jsonb),
           coalesce(pg_catalog.string_agg(size, ',' order by sort_order, size), 'ONE SIZE')
    into v_stock, v_size_stock, v_sizes from size_totals;
    update public.products set stock = v_stock, size_stock = v_size_stock, sizes = v_sizes where id = v_item.product_id;
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true, 'rpc', true, 'alreadyProcessed', false, 'receiptId', v_receipt_id,
    'receiptNumber', v_receipt_number, 'totalUnits', v_total_units, 'items', v_items_result
  );
  update public.inventory_receipts set result = v_result where id = v_receipt_id;
  insert into public.audit_logs (actor, action, entity, entity_id, metadata)
  values (v_actor, 'inventory_receipt_completed', 'inventory_receipt', v_receipt_id::text,
    pg_catalog.jsonb_build_object('receiptNumber', v_receipt_number, 'totalUnits', v_total_units, 'itemCount', v_count));
  return v_result;
exception when unique_violation then
  if sqlerrm like '%product_variants_barcode_unique%' then
    raise exception using errcode = '23505', message = 'INVENTORY_RECEIPT_BARCODE_CONFLICT';
  end if;
  raise;
end;
$$;

create or replace function public.inventory_receipt_runtime_health_rpc()
returns jsonb language sql security definer set search_path = '' stable
as $$
  select pg_catalog.jsonb_build_object(
    'ready', pg_catalog.to_regclass('public.inventory_receipts') is not null
      and pg_catalog.to_regclass('public.inventory_receipt_items') is not null
      and pg_catalog.to_regprocedure('public.inventory_receipt_complete_rpc(text,uuid,text,text,jsonb,text)') is not null
      and pg_catalog.has_function_privilege('service_role', 'public.inventory_receipt_complete_rpc(text,uuid,text,text,jsonb,text)', 'EXECUTE'),
    'version', '20260904184454'
  );
$$;

revoke all on function public.inventory_receipt_complete_rpc(text,uuid,text,text,jsonb,text) from public, anon, authenticated;
grant execute on function public.inventory_receipt_complete_rpc(text,uuid,text,text,jsonb,text) to service_role;
revoke all on function public.inventory_receipt_runtime_health_rpc() from public, anon, authenticated;
grant execute on function public.inventory_receipt_runtime_health_rpc() to service_role;

-- Supabase's platform DDL hooks may reapply broad service-role table grants
-- when a later public table is created. Restore the pre-existing immutable
-- operations-ledger boundaries explicitly at the end of this migration.
do $$
begin
  if pg_catalog.to_regclass('public.barcode_operations') is not null then
    execute 'revoke all on table public.barcode_operations from service_role';
    execute 'grant select, insert on table public.barcode_operations to service_role';
  end if;
  if pg_catalog.to_regclass('public.audit_logs') is not null then
    execute 'revoke all on table public.audit_logs from service_role';
    execute 'grant select on table public.audit_logs to service_role';
  end if;
end;
$$;

comment on table public.inventory_receipts is 'Atomic, idempotent completed receiving batches.';
comment on function public.inventory_receipt_complete_rpc(text,uuid,text,text,jsonb,text) is
  'Completes one multi-Variant receipt atomically, generates only missing internal barcodes, records movements, and synchronizes legacy stock projections.';

commit;

